inline f32 terrarium_height(u8 r, u8 g, u8 b) { return static_cast<f32>(r) * 256.0 + static_cast<f32>(g) + static_cast<f32>(b) / 256.0 - 32768.0; }
void bare_earth(std::vector<f32>& h, u32 n, f32 step, f32 open_m, f32 blur_m);
namespace jobs { unsigned int submit(const unsigned int& kind, const std::vector<unsigned char>& input); }
namespace jobs { bool take(const unsigned int& id, std::vector<unsigned char>& out); }
